983     + CC_OVERLAY_CSS
984     + """
985 * { box-sizing: border-box; }
986 body { margin: 0; padding: 0; font-family: var(--sans); background: var(--bg);
987   color: var(--fg); line-height: 1.5; font-size: var(--fs-body); }
988 a { color: var(--accent); transition: color var(--transition); }
989 button { transition: color var(--transition), border-color var(--transition),
990   background var(--transition); }
991 
992 /* Standardized motion: overlays slide/fade IN over the standard timing; the
993    symmetric exit is CCOverlay's (.cc-anim-out runs before the [hidden] toggle
994    so dismissal animates too — see pipeline/cc_overlay.py). */
995 @keyframes cc-slide-in-right { from { transform: translateX(18px); opacity: 0; }
996   to { transform: none; opacity: 1; } }
997 @keyframes cc-fade-in { from { opacity: 0; } to { opacity: 1; } }
998 @keyframes cc-pop-in { from { transform: translateX(-50%) scale(0.985); opacity: 0; }
999   to { transform: translateX(-50%) scale(1); opacity: 1; } }
1000 @keyframes cc-rise-in { from { transform: translateY(6px); opacity: 0; }
1001   to { transform: none; opacity: 1; } }
1002 
1003 /* Skip link — visible on :focus so keyboard users can bypass the top bar */
1004 .cc-skip { position: absolute; top: -200px; left: 0; z-index: 100;
1005   background: var(--accent); color: var(--accent-contrast);
1006   padding: 8px 16px; border-radius: 0 0 var(--radius) 0; font-weight: 600;
1007   text-decoration: none; font-size: var(--fs-body); }
1008 .cc-skip:focus-visible { top: 0; outline: none; }
1009 
1010 /* Visually hidden but available to assistive technology */
1011 .cc-sr-only { position: absolute; width: 1px; height: 1px; padding: 0;
1012   margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
1013 
1014 /* One sticky top bar: brand + section nav + utility links. The only other
1015    chrome is the active section's single sub-row (suppressed entirely for
1016    single-tab sections), so content starts ~90px from the top instead of ~200. */
1017 .cc-topbar { display: flex; align-items: center; gap: var(--sp-1);
1018   padding: 10px 24px; border-bottom: 1px solid var(--border);
1019   position: sticky; top: 0; background: var(--bg); z-index: 30; }
1020 .cc-brand { font-size: var(--fs-title); font-weight: 600; letter-spacing: 0.2px;
1021   margin-right: 18px; white-space: nowrap; }
1022 .cc-topnav { display: flex; gap: 2px; margin-right: auto; overflow-x: auto; }
1023 .cc-topnav .cc-tab { padding: 8px 13px; font-size: var(--fs-body); }
1024 .cc-links { display: flex; gap: 14px; margin: 0 14px 0 16px; }
1025 .cc-links a { color: var(--muted); text-decoration: none; font-size: var(--fs-body); }
1026 .cc-links a:hover { color: var(--accent); }
1027 .cc-stamp { color: var(--muted); font-size: var(--fs-caption); font-family: var(--mono);
1028   margin-left: 12px; white-space: nowrap; }
1029 .cc-tabs { display: flex; gap: 2px; padding: 0 16px; border-bottom: 1px solid var(--border);
1030   overflow-x: auto; background: var(--bg); }
1031 /* display:flex above beats the [hidden] UA rule — restate it. Without this
1032    every section's sub-row rendered at once (the old "four stacked menus"). */
1033 .cc-tabs[hidden] { display: none; }
1034 .cc-subtabs[data-single="1"] { display: none; }
1035 .cc-tab { background: transparent; border: none; border-bottom: 2px solid transparent;
1036   color: var(--muted); padding: 10px 16px; font-size: var(--fs-body); font-weight: 600;
1037   cursor: pointer; white-space: nowrap; font-family: var(--sans); }
1038 .cc-tab:hover { color: var(--fg); }
1039 .cc-tab.active { color: var(--fg); border-bottom-color: var(--accent); }
1040 .cc-topnav .cc-tab { border-bottom-width: 2px; }
1041 
1042 .cc-panels { padding: 22px 24px 64px; max-width: 1600px; margin: 0 auto; }
1043 
1044 /* Home: cockpit + the unified Inbox rail (PR3) */
1045 .cc-home-grid { display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: var(--sp-5);
1046   align-items: start; }
1047 @media (max-width: 1180px) { .cc-home-grid { grid-template-columns: 1fr; } }
1048 /* The main column is a grid item whose default min-width:auto lets a wide
1049    nowrap table (the Evaluation cockpit) grow past its track and spill into the
1050    sticky Inbox rail. Pin min-width:0 so the column honors its track, and give
1051    its tables their own horizontal scroll so wide content scrolls in-place
1052    instead of overlapping the rail. */
1053 .cc-home-main { min-width: 0; }
1054 .cc-home-main .lg { overflow-x: auto; }
1055 .cc-home-rail { position: sticky; top: 64px; min-width: 0; }
1056 .cc-home-rail-head { display: flex; align-items: baseline; justify-content: space-between;
1057   margin-bottom: var(--sp-2); }
1058 .cc-home-rail-head h2 { font-size: var(--fs-title); text-transform: uppercase;
1059   letter-spacing: 0.5px; margin: 0; }
1060 .cc-home-rail-links { font-size: var(--fs-caption); color: var(--muted); }
1061 .cc-home-rail-links a { color: var(--muted); text-decoration: none; }
1062 .cc-home-rail-links a:hover { color: var(--accent); }
1063 .cc-home-rail .ix-stream { max-height: calc(100vh - 140px); max-height: calc(100dvh - 140px); overflow-y: auto;
1064   padding-right: 2px; }
1065 /* Upcoming earnings, demoted into the rail as a collapsed section (the strip's
1066    own head is redundant with the summary, so hide it). */
1067 .cc-rail-upcoming { margin-bottom: var(--sp-3); }
1068 .cc-rail-upcoming > summary { cursor: pointer; list-style: none; padding: var(--sp-1) 0;
1069   font-size: var(--fs-body); text-transform: uppercase; letter-spacing: 0.5px; color: var(--muted); }
1070 .cc-rail-upcoming > summary::-webkit-details-marker { display: none; }
1071 /* NB: SHELL_CSS is a non-raw Python string — a single backslash before "25B8"
1072    would be eaten by Python as an OCTAL escape (0x15) and render literal "B8 "
1073    text before the summary. Keep the backslashes doubled so the served CSS
1074    carries the real escapes for the ▸ / ▾ marker glyphs. */
1075 .cc-rail-upcoming > summary::before { content: '\\25B8 '; }
1076 .cc-rail-upcoming[open] > summary::before { content: '\\25BE '; }
1077 .cc-rail-upcoming .up-strip-head { display: none; }
1078 .cc-panel[hidden] { display: none; }
1079 .cc-loading, .cc-empty { color: var(--muted); font-size: var(--fs-body); padding: 24px 4px; }
1080 /* Skeleton shimmer under the loading text (PR8) — feedback that the panel
1081    is alive, without a spinner library. */
1082 .cc-loading::after { content: ''; display: block; height: 10px; margin-top: 12px;
1083   border-radius: var(--radius-full); max-width: 420px;
1084   background: linear-gradient(90deg, var(--surface) 25%, var(--paper) 50%, var(--surface) 75%);
1085   background-size: 200% 100%; animation: cc-shimmer 1.2s ease-in-out infinite; }
1086 @keyframes cc-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
1087 
1088 /* Structured panel skeletons (S14): every ghost block shares the PR8 shimmer
1089    wash; the layouts echo the real panel anatomy (heading → KPI strip → table
1090    rows / card grid / input band) so the first paint reads as "the panel,
1091    loading" instead of "a spinner". Layout-only, token-skinned. */
1092 .cc-skel { padding: 12px 0 24px; }
1093 .cc-skel-line, .cc-skel-row, .cc-skel-kpi, .cc-skel-card, .cc-skel-input,
1094 .cc-skel-chip, .cc-skel-band, .cc-skel-frame {
1095   background: linear-gradient(90deg, var(--surface) 25%, var(--paper) 50%, var(--surface) 75%);
1096   background-size: 200% 100%; animation: cc-shimmer 1.2s ease-in-out infinite;
1097   border-radius: var(--radius); }
1098 .cc-skel-title { height: 16px; max-width: 240px; margin-bottom: 10px; }
1099 .cc-skel-sub { height: 10px; max-width: 460px; margin-bottom: 18px; }
1100 .cc-skel-table { display: flex; flex-direction: column; gap: 10px; }
1101 .cc-skel-row { height: 12px; }
1102 .cc-skel-row.cc-skel-th { height: 9px; max-width: 58%; }
1103 .cc-skel-row:nth-child(3n) { max-width: 94%; }
1104 .cc-skel-row:nth-child(3n+1) { max-width: 98%; }
1105 .cc-skel-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
1106   gap: 10px; margin-bottom: 18px; }
1107 .cc-skel-kpi { height: 64px; }
1108 .cc-skel-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
1109   gap: var(--sp-3); }
1110 .cc-skel-card { height: 96px; }
1111 .cc-skel-input { height: 38px; max-width: 760px; margin-bottom: 12px; }
1112 .cc-skel-chips { display: flex; gap: var(--sp-2); margin-bottom: 18px; }
1113 .cc-skel-chip { height: 20px; width: 92px; border-radius: var(--radius-full); }
1114 .cc-skel-band { height: 36px; margin-bottom: 14px; }
1115 .cc-skel-frame { height: calc(100vh - 280px); height: calc(100dvh - 280px); min-height: 360px; }
1116 @media (prefers-reduced-motion: reduce) {
1117   .cc-skel-line, .cc-skel-row, .cc-skel-kpi, .cc-skel-card, .cc-skel-input,
1118   .cc-skel-chip, .cc-skel-band, .cc-skel-frame, .cc-loading::after { animation: none; }
1119   /* Scrims are now the one shared .k-scrim (kit + CCOverlay handle its
1120      reduced-motion); the surfaces keep their own open keyframes. */
1121   .cc-drawer, .cc-palette, .cc-peek { animation: none; transition-duration: 0.01ms; }
1122 }
1123 
1124 /* The Holding tab's ticker picker is now a search combobox inside the holding
1125    fragment's utility band (UX9c, .cc-combo) — no shell-chrome <select>. */
1126 
1127 /* ============================================================
1128    Analytical / command-center panel vocabulary (dark)
1129    Lifted from analytical_dashboard_html + ticker_command_center so the
1130    lazy fragments + the inlined overview render identically here.
1131    ============================================================ */
1132 h1 { font-size: var(--fs-display); margin: 0 0 8px; font-weight: 600; }
1133 h2 { font-size: var(--fs-title); margin: 0 0 6px; font-weight: 600; }
1134 h3 { font-size: var(--fs-title); margin: 0; font-weight: 600; }
1135 /* Panels are elevation, not boxes: surface-on-bg with the one radius. */
1136 .panel { margin-bottom: 28px; background: var(--surface);
1137   border-radius: var(--radius); padding: 18px 20px; }
1138 .panel .sub { color: var(--muted); font-size: var(--fs-caption); margin: 0 0 16px; }
1139 .muted { color: var(--muted); }
1140 table { width: 100%; border-collapse: collapse; font-size: var(--fs-body);
1141   font-variant-numeric: tabular-nums; }
1142 th { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--border);
1143   font-size: var(--fs-caption); text-transform: uppercase;
1144   letter-spacing: 0.06em; color: var(--muted); font-weight: 600; }
1145 td { padding: 8px 10px; border-bottom: 1px solid var(--hairline); vertical-align: top; }
1146 tbody tr:hover td { background: var(--paper); }
1147 td.num { text-align: right; }
1148 td.muted { color: var(--muted); }
1149 .ticker-link { color: var(--fg); text-decoration: none; font-weight: 600; }
1150 .ticker-link:hover { color: var(--accent); }
1151 tr.tone-sell { background: color-mix(in srgb, var(--bad) 6%, transparent); }
1152 tr.tone-trim { background: color-mix(in srgb, var(--warn) 4%, transparent); }
1153 tr.tone-init { background: color-mix(in srgb, var(--ok) 6%, transparent); }
1154 tr.tx-buy { background: color-mix(in srgb, var(--ok) 4%, transparent); }
1155 tr.tx-sell { background: color-mix(in srgb, var(--bad) 2%, transparent); }
1156 td.trigger-cell { font-family: var(--sans); font-size: var(--fs-caption);
1157   text-transform: uppercase; }
1158 tr.tone-sell .trigger-cell { color: var(--bad); }
1159 tr.tone-trim .trigger-cell { color: var(--warn); }
1160 tr.tone-init .trigger-cell { color: var(--ok); }
1161 td.signal-strong { color: var(--ok); font-weight: 600; }
1162 td.signal-medium { color: var(--warn); }
1163 td.signal-weak { color: var(--muted); }
1164 /* Inline code tracks the surrounding step (mono renders larger than sans at
1165    equal px — 0.93em is the optical correction, not an importance level). */
1166 code { font-family: var(--mono); font-size: 0.93em; color: var(--fg-soft); }
1167 .cli-hint { font-family: var(--mono); font-size: var(--fs-caption); padding: 10px 12px;
1168   background: var(--paper); border-radius: var(--radius); color: var(--ok);
1169   overflow-x: auto; margin: 6px 0 0; }
1170 .panel-h3 { font-size: var(--fs-title); margin: 18px 0 8px; font-weight: 600;
1171   color: var(--fg); }
1172 /* Synthesis — a plain surface panel; no decorative left rail (rails are
1173    reserved for value status: tone-*/sig-* using --ok/--warn/--bad). */
1174 .synthesis-body { font-size: var(--fs-body); line-height: 1.65; }
1175 .synthesis-body h2, .synthesis-body h3, .synthesis-body h4,
1176 .synthesis-body h5, .synthesis-body h6 { color: var(--fg); margin-top: 1.2em; margin-bottom: 6px; }
1177 .synthesis-body h2 { font-size: var(--fs-title); }
1178 .synthesis-body h3 { font-size: var(--fs-title); }
1179 /* h4-h6 share the body size: the one prose boundary maps deep markdown headings
1180    (###/####) here, and panels already own the h2/h3 levels above them. */
1181 .synthesis-body h4, .synthesis-body h5, .synthesis-body h6 { font-size: var(--fs-body); color: var(--fg); }
1182 .synthesis-body strong { color: var(--fg); }
1183 .synthesis-body code { background: var(--paper); padding: 1px 5px; border-radius: var(--radius); }
1184 .synthesis-body ul { padding-left: 22px; }
1185 .synthesis-body li { margin-bottom: 4px; }
1186 .synthesis-body hr { border: none; border-top: 1px solid var(--border); margin: 16px 0; }
1187 /* Reread grid + cards */
1188 .reread-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); gap: var(--sp-3); margin-top: 8px; }
1189 .reread-card { background: var(--surface); border-radius: var(--radius); padding: 12px 14px; }
1190 .reread-card summary { cursor: pointer; list-style: none; display: flex; justify-content: space-between; align-items: baseline; font-size: var(--fs-title); font-weight: 600; }
1191 .reread-card summary::-webkit-details-marker { display: none; }
1192 .reread-card summary::before { content: '▸ '; color: var(--muted); font-family: var(--mono); }
1193 .reread-card[open] summary::before { content: '▾ '; }
1194 .reread-stamp { color: var(--muted); font-size: var(--fs-caption); font-family: var(--mono); font-weight: 400; }
1195 .reread-body { font-size: var(--fs-body); line-height: 1.55; margin-top: 10px; }
1196 .reread-body h2, .reread-body h3, .reread-body h4 { color: var(--fg); margin: 10px 0 4px; }
1197 .reread-body h2 { font-size: var(--fs-title); color: var(--fg); }
1198 .reread-body h3 { font-size: var(--fs-body); }
1199 .reread-body strong { color: var(--fg); }
1200 .reread-body ul { padding-left: 18px; }
1201 .reread-body hr { border: none; border-top: 1px solid var(--border); margin: 10px 0; }
1202 /* KPI strip + decisions calibration */
1203 .kpi-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; margin: 8px 0 12px; }
1204 .kpi-card { background: var(--paper); border-radius: var(--radius); padding: 10px 12px; text-align: center; }
1205 .kpi-card.tone-good { border-left: 3px solid var(--ok); }
1206 .kpi-card.tone-warn { border-left: 3px solid var(--warn); }
1207 .kpi-card.tone-bad { border-left: 3px solid var(--bad); }
