1211 .kpi-value { font-size: var(--fs-display); font-weight: 600; margin: 2px 0; color: var(--fg);
1212   font-variant-numeric: tabular-nums; }
1213 .kpi-sub { font-size: var(--fs-caption); color: var(--muted); font-family: var(--sans); }
1214 .calib-strip { display: flex; flex-direction: column; gap: 6px; margin: 8px 0 18px; }
1215 .calib-row { display: grid; grid-template-columns: 80px 1fr 110px; gap: 12px; align-items: center; font-size: var(--fs-caption); }
1216 .calib-label { color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; }
1217 .calib-bar { background: var(--paper); border-radius: var(--radius-full); height: 14px; overflow: hidden; }
1218 .calib-fill { background: linear-gradient(90deg, var(--bad) 0%, var(--warn) 50%, var(--ok) 100%); height: 100%; }
1219 .calib-value { font-family: var(--mono); color: var(--fg-soft); text-align: right; }
1220 .decisions-table td.outcome-correct { color: var(--ok); }
1221 .decisions-table td.outcome-wrong { color: var(--bad); }
1222 .decisions-table td.outcome-mixed { color: var(--warn); }
1223 .decisions-table td.outcome-pending { color: var(--muted); }
1224 /* LLM budget */
1225 .budget-table td code { font-family: var(--mono); font-size: 0.93em; color: var(--fg); background: transparent; padding: 0; }
1226 .burn-cell { width: 200px; padding: 6px 10px; }
1227 .burn-bar { width: 100%; height: 8px; background: var(--paper); border-radius: var(--radius-full); overflow: hidden; }
1228 .burn-fill { height: 100%; }
1229 .burn-ok { background: var(--ok); }
1230 .burn-warn { background: var(--warn); }
1231 .burn-over { background: var(--bad); }
1232 .budget-footer { margin-top: 12px; font-size: var(--fs-body); color: var(--fg-soft); }
1233 .budget-footer strong { color: var(--fg); }
1234 /* Inputs/selects: skinned by the shared control kit (ui/controls.py). */
1235 .budget-table input, .budget-table select { padding: 4px 6px; }
1236 .budget-table select { padding-right: 26px; }
1237 /* .budget-save composes the kit (.k-btn .k-btn-quiet .k-btn-sm) at its emitter. */
1238 /* Tier coverage strip */
1239 .tier-strip { background: var(--surface); border-radius: var(--radius);
1240   padding: 10px 14px; margin-bottom: 22px; font-size: var(--fs-body); display: flex;
1241   align-items: center; flex-wrap: wrap; gap: var(--sp-1); }
1242 .tier-strip-label { color: var(--muted); font-size: var(--fs-caption);
1243   text-transform: uppercase; letter-spacing: 0.06em; margin-right: 8px; }
1244 /* The tier strip's chips compose the kit (.k-chip + tones) at their emitter
1245    (render_tier_coverage_strip); only the in-chip count keeps a color modifier. */
