551 /* P4.1 canonical collapse idiom: <details class="panel"> with
552    <summary class="panel-head">. The ▸/▾ affordance rides on .panel-title.
553    (The financials line-item drill-down stays a JS row toggle — <tr> can't
554    nest inside <details>.) */
555 details.panel > summary { cursor: pointer; user-select: none; list-style: none; }
556 details.panel > summary::-webkit-details-marker { display: none; }
