551 /* P4.1 canonical collapse idiom: <details class="panel"> with
552    <summary class="panel-head">. The ▸/▾ affordance rides on .panel-title.
553    (The financials line-item drill-down stays a JS row toggle — <tr> can't
554    nest inside <details>.) */
555 details.panel > summary { cursor: pointer; user-select: none; list-style: none; }
556 details.panel > summary::-webkit-details-marker { display: none; }
557 details.panel > summary .panel-title::before {
558   content: '\25B8 ';
559   font-family: var(--mono); font-size: var(--fs-caption); color: var(--muted);
560 }
561 details.panel[open] > summary .panel-title::before { content: '\25BE '; }
562 details.panel:not([open]) > summary.panel-head { border-bottom: 0; }
563 details.panel > summary:hover { background: var(--paper); }
564 /* P4.3 cross-tab links: small accent links in the panel-meta that jump to a
565    related panel on another tab (data-xtab handler in workspace_script.JS).
566    The landing panel flashes briefly so the eye finds it after the switch. */
